def divisors_sum(n):
    """Return the sum of the proper divisors of n."""
    divisors = [1]  # Start with 1, which is a divisor of every number
    for i in range(2, int(n ** 0.5) + 1):
        if n % i == 0:
            divisors.append(i)
            if i != n // i:
                divisors.append(n // i)
    return sum(divisors)

def amicable_numbers_sum(max_num):
    """Return the sum of all amicable numbers up to max_num."""
    amicable_sums = set()
    for num in range(2, max_num + 1):
        d_sum = divisors_sum(num)
        if d_sum > num and divisors_sum(d_sum) == num:
            amicable_sums.add(num)
            amicable_sums.add(d_sum)
    return sum(amicable_sums)

