def pancake_sort(arr):
    size = len(arr)

    for end in range(size, 1, -1):
        # Find the index of the maximum element in arr[0:end]
        max_index = arr.index(max(arr[0:end]))

        # If the maximum element is not at the end, flip it to the front
        if max_index != end - 1:
            if max_index != 0:
                arr = flip(arr, max_index + 1)  # Flip to bring max to the front
            arr = flip(arr, end)               # Flip to move max to the end
    return arr

